<?php
// Run against an isolated database on the development router, never the live site.
$base='http://127.0.0.1:8097';$cookie=tempnam(sys_get_temp_dir(),'parthvi-cookie-');$passed=0;
function request($path,$data=null){global $base,$cookie;$c=curl_init($base.$path);curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HEADER=>true,CURLOPT_COOKIEJAR=>$cookie,CURLOPT_COOKIEFILE=>$cookie,CURLOPT_FOLLOWLOCATION=>false]);if($data!==null){curl_setopt($c,CURLOPT_POST,true);curl_setopt($c,CURLOPT_POSTFIELDS,$data);} $r=curl_exec($c);if($r===false)throw new Exception(curl_error($c));$n=curl_getinfo($c,CURLINFO_HEADER_SIZE);$code=curl_getinfo($c,CURLINFO_RESPONSE_CODE);curl_close($c);return ['status'=>$code,'headers'=>substr($r,0,$n),'body'=>substr($r,$n)];}
function check($condition,$message){global $passed;if(!$condition)throw new Exception('FAIL: '.$message);$passed++;echo "PASS: $message\n";}
function form($html,$class='editor-form'){$doc=new DOMDocument();@$doc->loadHTML($html);$xp=new DOMXPath($doc);$fields=$xp->query('//form[contains(@class,"'.$class.'")]//input | //form[contains(@class,"'.$class.'")]//textarea');$data=[];foreach($fields as $f){$name=$f->getAttribute('name');if(!$name||in_array($f->getAttribute('type'),['file','submit'])||($f->getAttribute('type')==='checkbox'&&!$f->hasAttribute('checked')))continue;$data[$name]=$f->nodeName==='textarea'?$f->textContent:$f->getAttribute('value');}return $data;}
function token($html){preg_match('/name="csrf" value="([a-f0-9]+)"/',$html,$m);return $m[1]??'';}
function edit_id($body,$section,$name){$d=new DOMDocument();@$d->loadHTML($body);$xp=new DOMXPath($d);foreach($xp->query('//tr') as $r)if(strpos($r->textContent,$name)!==false){$a=$xp->query('.//a[contains(@href,"edit=")]',$r)->item(0);if($a){parse_str(parse_url($a->getAttribute('href'),PHP_URL_QUERY),$q);return $q['edit'];}}return null;}
try{
$r=request('/admin/');check($r['status']===302&&str_contains($r['headers'],'login.php'),'Admin requires authentication');
$r=request('/admin/login.php');$csrf=token($r['body']);$r=request('/admin/login.php',['csrf'=>$csrf,'email'=>'admin@gmail.com','password'=>'wrong']);check(str_contains($r['body'],'Email or password is incorrect'),'Wrong credentials rejected');
$r=request('/admin/login.php',['csrf'=>$csrf,'email'=>'admin@gmail.com','password'=>'123456']);check($r['status']===302,'Default credentials work');
$r=request('/admin/index.php?section=settings');$settings=form($r['body']);$bad=$settings;$bad['csrf']='bad';$r=request('/admin/index.php?section=settings',$bad);check($r['status']===403,'CSRF is required for changes');
$bad=$settings;$bad['instagram']='javascript:alert(1)';$r=request('/admin/index.php?section=settings',$bad);check(str_contains($r['body'],'valid https:// URL'),'Unsafe social URL rejected');
$settings['email']='sales@example.com';$r=request('/admin/index.php?section=settings',$settings);check($r['status']===302,'Settings save');$r=request('/contact');check(str_contains($r['body'],'mailto:sales@example.com'),'Contact email updates publicly');
$r=request('/admin/index.php?section=pages&slug=index');$page=form($r['body']);$page['copy_h1_1']='<script>alert("test")</script> New heading';$r=request('/admin/index.php?section=pages&slug=index',$page);check($r['status']===302,'Page content saves');$r=request('/');check(str_contains($r['body'],'&lt;script&gt;')&&!str_contains($r['body'],'<script>alert("test")'),'Stored content is escaped');$r=request('/admin/index.php?section=pages&slug=index',$page);check(str_contains($r['body'],'changed in another tab'),'Stale edits do not overwrite changes');
$r=request('/admin/index.php?section=products&edit=new');$product=form($r['body']);$product=array_merge($product,['name'=>'Test product','slug'=>'test-product','category'=>'Test category','short'=>'Test introduction','description'=>'Test description','origin'=>'India','packing'=>'25 kg','grades'=>"Grade A\nGrade B",'applications'=>'Food','specifications'=>'Purity: 99%','image'=>new CURLFile(dirname(__DIR__).'/assets/images/parthvi-exim-client-logo.png','image/png','product.png')]);$r=request('/admin/index.php?section=products&edit=new',$product);check($r['status']===302,'Product and validated image upload save');
$r=request('/admin/index.php?section=products');$id=edit_id($r['body'],'products','Test product');check((bool)$id,'New product appears in admin');$r=request('/products');check(str_contains($r['body'],'href="products/test-product"'),'Published product appears publicly');
$r=request('/admin/index.php?section=products&edit='.$id);$draft=form($r['body']);unset($draft['published']);$r=request('/admin/index.php?section=products&edit='.$id,$draft);check($r['status']===302,'Product can be saved as draft');$r=request('/products');check(!str_contains($r['body'],'href="products/test-product"'),'Draft product hidden publicly');
$r=request('/admin/index.php?section=products&edit='.$id);$del=form($r['body']);$del['action']='delete_record';$r=request('/admin/index.php?section=products&edit='.$id,$del);check($r['status']===302,'Product delete succeeds');
$r=request('/admin/index.php?section=certificates&edit=new');$cert=form($r['body']);$cert=array_merge($cert,['title'=>'Test certificate','label'=>'TEST','description'=>'Test PDF','file'=>new CURLFile(dirname(__DIR__).'/assets/documents/parthvi-exim-iec-certificate.pdf','application/pdf','test.pdf')]);$r=request('/admin/index.php?section=certificates&edit=new',$cert);check($r['status']===302,'PDF upload succeeds without preview');$r=request('/certificates');check(str_contains($r['body'],'Test certificate')&&str_contains($r['body'],'certificate-placeholder'),'PDF fallback preview renders');
$r=request('/admin/index.php?section=certificates&edit=new');$badCert=form($r['body']);$badCert=array_merge($badCert,['title'=>'Bad','label'=>'BAD','description'=>'Invalid file','file'=>new CURLFile(__FILE__,'application/pdf','test.pdf')]);$r=request('/admin/index.php?section=certificates&edit=new',$badCert);check(str_contains($r['body'],'valid PDF document'),'Spoofed PDF rejected');
$r=request('/contact');$inquiry=['csrf'=>token($r['body']),'name'=>'Test buyer <script>','email'=>'buyer@example.com','phone'=>'+91 1234567890','country'=>'India','company'=>'Test Co','product'=>'general','quantity'=>"5 tonnes\n25 kg bags",'website'=>''];$invalid=$inquiry;$invalid['email']='bad';$r=request('/contact',$invalid);check($r['status']===422,'Inquiry email validation');$r=request('/contact',$inquiry);check($r['status']===303,'Inquiry saved with redirect');$r=request('/contact');check(str_contains($r['body'],'has been received'),'Inquiry success confirmation');$r=request('/admin/index.php?section=inquiries');check(str_contains($r['body'],'Test buyer &lt;script&gt;'),'Inquiry appears safely in admin inbox');preg_match('/section=inquiries&amp;id=(\d+)|section=inquiries&id=(\d+)/',$r['body'],$m);$iid=$m[1]?:($m[2]??'');check((bool)$iid,'Inquiry can be opened');$r=request('/admin/index.php?section=inquiries&id='.$iid);$csrf=token($r['body']);$r=request('/admin/index.php?section=inquiries&id='.$iid,['csrf'=>$csrf,'action'=>'inquiry','id'=>$iid,'status'=>'Closed']);check($r['status']===302,'Inquiry status updates');$r=request('/admin/index.php?section=inquiries&id='.$iid);check(str_contains($r['body'],'Closed'),'Closed status persisted');
$r=request('/admin/index.php?section=account');$account=form($r['body']);$account=array_merge($account,['current_password'=>'123456','new_password'=>'ChangedPass123!','confirm_password'=>'ChangedPass123!']);$r=request('/admin/index.php?section=account',$account);check($r['status']===302,'Password change succeeds');$r=request('/admin/index.php');$csrf=token($r['body']);request('/admin/logout.php',['csrf'=>$csrf]);$r=request('/admin/');check($r['status']===302,'Logout revokes access');$r=request('/admin/login.php');$csrf=token($r['body']);$r=request('/admin/login.php',['csrf'=>$csrf,'email'=>'admin@gmail.com','password'=>'123456']);check(str_contains($r['body'],'incorrect'),'Old password no longer works');$r=request('/admin/login.php',['csrf'=>$csrf,'email'=>'admin@gmail.com','password'=>'ChangedPass123!']);check($r['status']===302,'New password works');
echo "\n$passed checks passed. Test data is isolated in PARTHVI_DB_NAME.\n";
}finally{unlink($cookie);}
